  municipioFromCredito(credito?: Credito) {
    if (!credito) return '';
    const pf = credito.datos_persona_fisica
    const pm = credito.datos_personas_morales
    if (pf) {
      const municipio = pf.datos_personales?.ciudades?.nombre
      const localidad = pf.datos_personales?.localidad
      if (municipio && municipio !== '') return municipio
      if (localidad) return localidad;
    }
    const municipio = pm?.ciudades?.nombre
    const localidad = pm?.localidad
    if (municipio && municipio !== '') return municipio
    if (localidad) return localidad;
    return credito.sucursales?.nombre
  }

